  ja.ledger = { cols: ["言える(L1)— 凍結の判定・値の写し", "記述 — 凍結の判定でない集計", "読み(L3)— 主 session・採否は先生", "言えない — 平叙文"], tag: { L1: "L1", D: "記述", L3: "L3", x: "×" }, get rows() { return LG("ja"); } };
